using Rhino;using Rhino.DocObjects;using Rhino.Geometry;
namespace RhinoContextAssist;
internal static class SelectionAnalyzer{internal static SelectionContext Analyze(RhinoDoc d){var s=d.Objects.GetSelectedObjects(false,false).ToList();if(s.Count==0)s=d.Objects.Where(o=>o.GetSelectedSubObjects()?.Length>0).ToList();if(s.Count==0)return new(SelectionKind.None,0,"Keine Auswahl",Point3d.Unset);var box=BoundingBox.Empty;foreach(var o in s)box.Union(o.Geometry.GetBoundingBox(true));var a=box.Center;if(s.Count>1)return new(SelectionKind.Multiple,s.Count,$"{s.Count} Objekte",a);var x=s[0];var sub=x.GetSelectedSubObjects();if(sub is{Length:>0})return Sub(x,sub[0],a);if(x is InstanceObject)return new(SelectionKind.Block,1,"Blockinstanz",a);return x.Geometry switch{Curve c when c.IsClosed&&c.IsPlanar()=>new(SelectionKind.ClosedPlanarCurve,1,"Geschlossene planare Kurve",a),Curve=>new(SelectionKind.Curve,1,"Kurve",a),Brep b when b.IsSolid=>new(SelectionKind.SolidBrep,1,"Geschlossener Körper",a),Brep b when b.Faces.Count==1&&b.Faces[0].TryGetPlane(out _)=>new(SelectionKind.PlanarSurface,1,"Planare Fläche",a),Brep b when b.Faces.Count==1=>new(SelectionKind.Surface,1,"Fläche",a),Brep b=>new(SelectionKind.Brep,1,"Flächenverband",a,!b.IsSolid,b.Faces.Count>1),Mesh=>new(SelectionKind.Mesh,1,"Polygonnetz",a),SubD=>new(SelectionKind.SubD,1,"SubD",a),_=>new(SelectionKind.Mixed,1,x.ObjectType.ToString(),a)};}
 static SelectionContext Sub(RhinoObject o,ComponentIndex i,Point3d a){var n=i.ComponentIndexType.ToString();var b=o.Geometry as Brep;if(n=="BrepFace"&&b!=null){var f=b.Faces[i.Index];return f.TryGetPlane(out _)?new(SelectionKind.PlanarBrepFace,1,"Planare Teilfläche",a):new(SelectionKind.BrepFace,1,"Teilfläche",a);}if(n=="BrepEdge")return new(SelectionKind.BrepEdge,1,"Kante",a);if(o.Geometry is Mesh)return n.Contains("Face")?new(SelectionKind.MeshFace,1,"Polygonnetzseite",a):n.Contains("Edge")?new(SelectionKind.MeshEdge,1,"Polygonnetzkante",a):new(SelectionKind.MeshVertex,1,"Polygonnetzpunkt",a);if(o.Geometry is SubD)return n.Contains("Face")?new(SelectionKind.SubDFace,1,"SubD-Seite",a):n.Contains("Edge")?new(SelectionKind.SubDEdge,1,"SubD-Kante",a):new(SelectionKind.SubDVertex,1,"SubD-Punkt",a);return new(SelectionKind.Mixed,1,"Unterobjekt",a);}}
